    {"path": "/api/v1/image/ocr", "method": "POST", "summary": "通用 OCR 文字识别", "tags": ["Image"], "operation_id": "post-image-ocr", "parameters": [], "body_params": [{"name": "file", "type": "string", "description": "待识别的图片文件。支持 JPG、JPEG、PNG、BMP、GIF、WebP 等常见格式，最大不超过 10MB。请勿与 url 或 image_base64 同时提交。", "required": False}, {"name": "url", "type": "string", "description": "公网可直接访问的图片地址。请勿与 file 或 image_base64 同时提交。", "required": False}, {"name": "image_base64", "type": "string", "description": "图片的 Base64 字符串。可以传完整 Data URI，也可以只传纯 Base64 内容。请勿与 file 或 url 同时提交。", "required": False}, {"name": "image_name", "type": "string", "description": "自定义图片文件名。传链接或纯 Base64 时建议一起传，便于保留或推断扩展名。", "required": False}, {"name": "need_location", "type": "string", "description": "是否返回文字坐标信息。请传 `true` 或 `false`，不传时默认是 `true`。", "required": False}, {"name": "return_markdown", "type": "string", "description": "是否额外返回整理后的 Markdown 文本。请传 `true` 或 `false`，不传时默认是 `false`。", "required": False}, {"name": "enable_cls", "type": "string", "description": "是否开启额外的文字方向校正。请传 `true` 或 `false`，不传时默认是 `false`。", "required": False}], "short_name": "image.ocr"},
    {"path": "/api/v1/image/nsfw", "method": "POST", "summary": "图片敏感检测", "tags": ["Image"], "operation_id": "post-image-nsfw", "parameters": [], "body_params": [{"name": "file", "type": "string", "description": "要检测的图片文件。支持 JPG、JPEG、PNG、GIF、WebP 格式，最大 20MB。", "required": False}, {"name": "url", "type": "string", "description": "图片的 URL 地址。如果同时提供 file 和 url，将优先使用 file。", "required": False}], "short_name": "image.nsfw"},
    {"path": "/api/v1/watermark/embed", "method": "POST", "summary": "添加图片隐水印", "tags": ["水印与 AIGC 标识"], "operation_id": "post-watermark-embed", "parameters": [], "body_params": [{"name": "file", "type": "string", "description": "要加水印的图片文件，支持 PNG、JPEG、WebP。", "required": False}, {"name": "url", "type": "string", "description": "图片链接，需确保公网可直接访问。", "required": False}, {"name": "image_base64", "type": "string", "description": "图片的 Base64 编码，可携带或省略 data: 前缀。", "required": False}, {"name": "payload", "type": "string", "description": "需要嵌入图片的隐形标识内容。", "required": True}, {"name": "out_format", "type": "string", "description": "输出的图片格式。不填则默认保持与原图一致。", "required": False}, {"name": "jpeg_quality", "type": "integer", "description": "输出 JPEG 时的图像质量，范围 1 到 100。", "required": False}, {"name": "ecc", "type": "string", "description": "纠错强度，决定水印能抗多少损坏、最多能嵌入多少字符：纠错越强，图片被压缩、裁剪后越容易读回，但能嵌入的字符越少。不填默认 `BCH_4`。[查看各档位](#enum-list)", "required": False}, {"name": "model_type", "type": "string", "description": "水印档位，在稳健性和画质之间取舍。不填默认 `B`。[查看各档位](#enum-list)", "required": False}, {"name": "strength", "type": "number", "description": "水印写入强度，默认 `1.0`。调高更不容易被压缩、转发破坏，但更可能被肉眼看出；调低更隐蔽，但抗损坏能力下降。", "required": False}], "short_name": "watermark.embed"},
    {"path": "/api/v1/watermark/decode", "method": "POST", "summary": "提取图片隐水印", "tags": ["水印与 AIGC 标识"], "operation_id": "post-watermark-decode", "parameters": [], "body_params": [{"name": "file", "type": "string", "description": "要提取水印的图片文件，支持 PNG、JPEG、WebP。", "required": False}, {"name": "url", "type": "string", "description": "图片链接，需确保公网可直接访问。", "required": False}, {"name": "image_base64", "type": "string", "description": "图片的 Base64 编码，可携带或省略 data: 前缀。", "required": False}, {"name": "ecc", "type": "string", "description": "纠错强度，必须和嵌入时填的一致，否则无法正确提取。[查看各档位](#enum-list)", "required": False}, {"name": "model_type", "type": "string", "description": "水印档位，必须和嵌入时用的一致，否则无法正确提取。[查看各档位](#enum-list)", "required": False}], "short_name": "watermark.decode"},
    {"path": "/api/v1/watermark/label", "method": "POST", "summary": "添加 AI 生成内容标识", "tags": ["水印与 AIGC 标识"], "operation_id": "post-watermark-label", "parameters": [], "body_params": [{"name": "file", "type": "string", "description": "待处理的图片文件，支持 PNG、JPEG、WebP。", "required": False}, {"name": "url", "type": "string", "description": "图片链接，需确保公网可直接访问。", "required": False}, {"name": "image_base64", "type": "string", "description": "图片的 Base64 编码，可携带或省略 data: 前缀。", "required": False}, {"name": "content_producer", "type": "string", "description": "必需：生成此图片的服务提供者编码（27 位）。", "required": True}, {"name": "label", "type": "string", "description": "生成场景分类：1 代表 AI 生成合成，2 代表人机协同，3 代表其他情况。默认取值为 1。", "required": False}, {"name": "produce_id", "type": "string", "description": "服务侧内部生成的内容编号（可选）。", "required": False}, {"name": "content_propagator", "type": "string", "description": "负责内容传播的服务提供者编码（27 位，可选）。", "required": False}, {"name": "propagate_id", "type": "string", "description": "传播方侧的内容编号（可选）。", "required": False}, {"name": "skip_metadata", "type": "boolean", "description": "是否跳过写入元数据标识。若设置为 true，则必须开启另外两项中的至少一项。", "required": False}, {"name": "explicit_label", "type": "boolean", "description": "是否叠加可见的角标文字标识。默认不开启。", "required": False}, {"name": "explicit_text", "type": "string", "description": "角标显示的具体文案，默认为“AI 生成”。", "required": False}, {"name": "explicit_position", "type": "string", "description": "角标所处的相对位置，默认为右下角。", "required": False}, {"name": "explicit_height_ratio", "type": "number", "description": "角标文字高度占画面短边的比例。低于 0.05 会自动补偿至国标下限要求。", "required": False}, {"name": "embed_watermark", "type": "boolean", "description": "是否额外注入抗压缩的隐形水印。默认不开启。", "required": False}, {"name": "watermark_payload", "type": "string", "description": "隐形水印中所记载的标识内容。", "required": False}, {"name": "out_format", "type": "string", "description": "输出的图片格式。不填则默认保持与原图一致。", "required": False}, {"name": "jpeg_quality", "type": "integer", "description": "输出 JPEG 时的图像质量，范围 1 到 100。", "required": False}], "short_name": "watermark.label"},
    {"path": "/api/v1/watermark/producer-code", "method": "POST", "summary": "生成 AIGC 服务提供者编码", "tags": ["水印与 AIGC 标识"], "operation_id": "post-watermark-producer-code", "parameters": [], "body_params": [{"name": "subject_type", "type": "string", "description": "主体类型是组织还是个人。", "required": False}, {"name": "binding", "type": "string", "description": "主体绑定的证件类型。组织需使用统一社会信用代码；个人可选身份证、手机号、护照或网号。", "required": False}, {"name": "identifier", "type": "string", "description": "证件号实际内容。长度需匹配选择的类型（如统一社会信用代码 18 位、手机号 11 位）。", "required": False}, {"name": "service_type", "type": "string", "description": "服务角色类型（仅在提供模型应用码时一同生效）。", "required": False}, {"name": "model_code", "type": "string", "description": "4 位自定义模型或应用码（可选）。未提供时扩展段将默认填充 00000。", "required": False}, {"name": "code", "type": "string", "description": "待校验的 27 位现成编码。填写后接口将直接执行合法性校验。", "required": False}], "short_name": "watermark.producer-code"},
    {"path": "/api/v1/misc/hotboard", "method": "GET", "summary": "查询热榜", "tags": ["Misc"], "operation_id": "get-misc-hotboard", "parameters": [{"name": "type", "in": "query", "required": True, "type": "string", "description": "你想要查询的热榜平台。请从[支持的平台列表](#enum-list)中选择。", "default": None, "enum": ["bilibili", "acfun", "weibo", "zhihu", "zhihu-daily", "douyin", "xiaohongshu", "kuaishou", "douban-movie", "douban-group", "tieba", "hupu", "ngabbs", "v2ex", "52pojie", "hostloc", "coolapk", "baidu", "thepaper", "toutiao", "qq-news", "sina", "sina-news", "netease-news", "huxiu", "ifanr", "sspai", "ithome", "ithome-xijiayi", "juejin", "jianshu", "guokr", "36kr", "51cto", "csdn", "nodeseek", "hellogithub", "lol", "genshin", "honkai", "starrail", "netease-music", "qq-music", "weread", "weatheralarm", "earthquake", "history"]}, {"name": "time", "in": "query", "required": False, "type": "integer", "description": "时光机模式：毫秒时间戳，返回该时间附近最近可展示的历史热榜快照。不传则返回当前实时热榜。", "default": None, "enum": None}, {"name": "keyword", "in": "query", "required": False, "type": "string", "description": "搜索模式：搜索关键词，在指定历史时间范围内搜索包含该关键词的条目。需配合 time_start 和 time_end 使用。", "default": None, "enum": None}, {"name": "time_start", "in": "query", "required": False, "type": "integer", "description": "搜索模式必填：搜索起始时间戳（毫秒），需位于该平台历史数据覆盖范围内。", "default": None, "enum": None}, {"name": "time_end", "in": "query", "required": False, "type": "integer", "description": "搜索模式必填：搜索结束时间戳（毫秒），需晚于 time_start 且位于该平台历史数据覆盖范围内。", "default": None, "enum": None}, {"name": "limit", "in": "query", "required": False, "type": "integer", "description": "搜索模式下最大返回条数，默认 50，最大 200。", "default": None, "enum": None}], "short_name": "misc.hotboard"},
