    {"path": "/api/v1/misc/randomnumber", "method": "GET", "summary": "随机数生成", "tags": ["Misc"], "operation_id": "get-misc-randomnumber", "parameters": [{"name": "min", "in": "query", "required": False, "type": "integer", "description": "生成随机数的最小值（包含）。", "default": 1, "enum": None}, {"name": "max", "in": "query", "required": False, "type": "integer", "description": "生成随机数的最大值（包含）。", "default": 100, "enum": None}, {"name": "count", "in": "query", "required": False, "type": "integer", "description": "需要生成的随机数的数量。", "default": 1, "enum": None}, {"name": "allow_repeat", "in": "query", "required": False, "type": "boolean", "description": "是否允许生成的多个数字中出现重复值。", "default": False, "enum": None}, {"name": "allow_decimal", "in": "query", "required": False, "type": "boolean", "description": "是否生成小（浮点）数。如果为 false，则只生成整数。", "default": False, "enum": None}, {"name": "decimal_places", "in": "query", "required": False, "type": "integer", "description": "如果 `allow_decimal=true`，这里可以指定小数的位数。", "default": 2, "enum": None}], "short_name": "misc.randomnumber"},
