    {"path": "/api/v1/misc/weather", "method": "GET", "summary": "查询天气", "tags": ["Misc"], "operation_id": "get-misc-weather", "parameters": [{"name": "city", "in": "query", "required": False, "type": "string", "description": "城市名称，支持中文（`北京`）和英文（`Tokyo`）。可选参数，不传时会尝试 IP 自动定位。", "default": None, "enum": None}, {"name": "adcode", "in": "query", "required": False, "type": "string", "description": "城市行政区划代码（如 `110000`），优先级高于 city。可选参数，不传时会尝试 IP 自动定位。", "default": None, "enum": None}, {"name": "extended", "in": "query", "required": False, "type": "boolean", "description": "返回扩展气象字段（体感温度、能见度、气压、紫外线、降水量、云量、空气质量指数及污染物分项数据）。", "default": None, "enum": [False, True]}, {"name": "forecast", "in": "query", "required": False, "type": "boolean", "description": "返回多天预报数据（最多7天），含每天的最高温度、最低温度、白天夜间天气、风向风力、日出日落等。", "default": None, "enum": [False, True]}, {"name": "hourly", "in": "query", "required": False, "type": "boolean", "description": "返回逐小时预报（24小时），含温度、天气、风向风速、湿度、降水概率等。", "default": None, "enum": [False, True]}, {"name": "minutely", "in": "query", "required": False, "type": "boolean", "description": "返回分钟级降水预报（仅国内城市），精确到2分钟。", "default": None, "enum": [False, True]}, {"name": "indices", "in": "query", "required": False, "type": "boolean", "description": "返回18项生活指数（穿衣、紫外线、洗车、晾晒、空调、感冒、运动、舒适度、出行、钓鱼、过敏、防晒、心情、啤酒、雨伞、交通、空气净化器、花粉）。", "default": None, "enum": [False, True]}, {"name": "lang", "in": "query", "required": False, "type": "string", "description": "返回语言。`zh` 返回中文（默认），`en` 返回英文。城市名翻译覆盖 7000+ 城市。生活指数（`indices`）目前仅支持中文。", "default": "zh", "enum": ["zh", "en"]}], "short_name": "misc.weather"},
