    {"path": "/api/v1/misc/holiday-calendar", "method": "GET", "summary": "查询节假日与万年历", "tags": ["Misc"], "operation_id": "get-misc-holiday-calendar", "parameters": [{"name": "date", "in": "query", "required": False, "type": "string", "description": "按天查询时填写这个参数，例如查某一天。格式：`YYYY-MM-DD`。和 `month`、`year` 三选一。", "default": None, "enum": None}, {"name": "month", "in": "query", "required": False, "type": "string", "description": "按月查询时填写这个参数，例如查某个月。格式：`YYYY-MM`。和 `date`、`year` 三选一。", "default": None, "enum": None}, {"name": "year", "in": "query", "required": False, "type": "string", "description": "按年查询时填写这个参数，例如查某一年。格式：`YYYY`。和 `date`、`month` 三选一。", "default": None, "enum": None}, {"name": "timezone", "in": "query", "required": False, "type": "string", "description": "时区名称，默认 Asia/Shanghai。", "default": "Asia/Shanghai", "enum": None}, {"name": "holiday_type", "in": "query", "required": False, "type": "string", "description": "节日筛选类型，默认 all。", "default": "all", "enum": ["all", "legal", "legal_rest", "legal_workday", "solar", "lunar", "term"]}, {"name": "include_nearby", "in": "query", "required": False, "type": "boolean", "description": "是否返回前后最近节日，仅 date 模式生效，默认 false。month/year 模式会忽略此参数。", "default": False, "enum": [False, True]}, {"name": "nearby_limit", "in": "query", "required": False, "type": "integer", "description": "返回最近节日数量限制，默认 7，最大 30。仅 date 模式 + include_nearby=true 生效。", "default": 7, "enum": None}, {"name": "exclude_past", "in": "query", "required": False, "type": "boolean", "description": "传 true 时，会过滤今天之前已经过去的节日。默认 false。", "default": False, "enum": [False, True]}], "short_name": "misc.holiday-calendar"},
