    {"path": "/api/v1/misc/weather/history", "method": "GET", "summary": "查询历史天气", "tags": ["Misc"], "operation_id": "get-misc-weather-history", "parameters": [{"name": "city", "in": "query", "required": False, "type": "string", "description": "城市名称，支持中文或英文；可选，不传 city/adcode 时会尝试 IP 自动定位。", "default": None, "enum": None}, {"name": "adcode", "in": "query", "required": False, "type": "string", "description": "6 位行政区划代码，优先级高于 city。", "default": None, "enum": None}, {"name": "start_date", "in": "query", "required": False, "type": "string", "description": "起始日期，格式 YYYY-MM-DD；与 end_date 搭配使用。", "default": None, "enum": None}, {"name": "end_date", "in": "query", "required": False, "type": "string", "description": "结束日期，格式 YYYY-MM-DD，默认昨天。", "default": None, "enum": None}, {"name": "days", "in": "query", "required": False, "type": "integer", "description": "回看天数，1-366，默认 365；仅在未指定 start_date 时生效。", "default": 365, "enum": None}, {"name": "lang", "in": "query", "required": False, "type": "string", "description": "返回语言：zh（默认）或 en。", "default": "zh", "enum": ["zh", "en"]}], "short_name": "misc.weather.history"},
